"""Embed the incumbent town vectors/fonts and exact theme colors in the shell.

The export shell must load before the PCK. Inline assets avoid adding an
export/copy step or relying on Godot's internal res:// paths from the browser.
"""
from pathlib import Path
from io import BytesIO
import re,base64,sys
from fontTools.ttLib import TTFont
R=Path(__file__).resolve().parents[1]
shell=R/'project/web_shell.html'
theme=(R/'project/ui/town_theme_r21.gd').read_text(encoding='utf-8')
def color(name):
 return '#'+re.search(r'const '+name+r'=Color\("([a-f0-9]+)"\)',theme)[1]
def font(name):
 path=re.search(r'const '+name+r'=preload\("res://([^\"]+)"\)',theme)[1]
 f=TTFont(R/'project'/path,recalcTimestamp=False);f.flavor='woff2';b=BytesIO();f.save(b)
 return base64.b64encode(b.getvalue()).decode()
def vector(name,cls):
 s=(R/'project/assets/ui-r21'/name).read_text(encoding='utf-8')
 return s.replace('<svg ',f'<svg class="{cls}" aria-hidden="true" focusable="false" ',1)
def bitmap(name):
 return 'data:image/webp;base64,'+base64.b64encode((R/'project/shell-assets'/name).read_bytes()).decode()
style='''
/* Town theme: generated by tools/look_r24_shell_assets.py; source fonts/vectors unchanged. */
@font-face{font-family:Abyss;src:url(data:font/woff2;base64,BODY_FONT) format("woff2");font-weight:500;font-display:swap}
@font-face{font-family:Abyss;src:url(data:font/woff2;base64,BOLD_FONT) format("woff2");font-weight:850;font-display:swap}
:root{color-scheme:light;--paper:PAPER;--ink:INK;--red:ACTION_RED;--muted:MUTED;--pale:PALE}
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:var(--paper);color:var(--ink);font:500 15px/1.6 Abyss,sans-serif}
::selection{background:var(--red);color:var(--paper)}#canvas{display:block;touch-action:none}#canvas:focus{outline:none}
#status{position:fixed;inset:0;z-index:2;overflow:auto;background:var(--paper);scrollbar-color:var(--ink) var(--paper)}
.screen{position:relative;isolation:isolate;width:100%;max-width:430px;min-height:100%;margin:auto;display:flex;flex-direction:column;align-items:center;padding:0 0 calc(20px + env(safe-area-inset-bottom));background:var(--paper)}
.poster{position:relative;isolation:isolate;flex:none;width:min(100%,calc((100svh - 220px)*390/530));aspect-ratio:390/530;overflow:hidden}
.town-ground{position:absolute;inset:0;width:100%;height:100%}h1{position:absolute;inset:0 0 auto;height:43.9623%;margin:0;line-height:1}h1 svg{display:block;width:100%;height:100%}
.city-left,.city-right,.sweep,.portrait{position:absolute}.city-left{left:0;top:62.2642%;width:26.4103%;height:24.1509%}.city-right{left:85.8974%;top:47.9245%;width:14.1026%;height:37.9245%}.sweep{left:-6.1538%;top:53.9623%;width:115.3846%;height:46.4151%}.portrait{left:12.8205%;top:15.6604%;width:87.1795%;height:84.3396%}
.status-box{width:calc(100% - 36px);margin-top:auto}
.status-box{padding:18px 0 0;border-top:3px solid var(--ink);background:var(--paper)}.status-head{display:flex;justify-content:space-between;gap:10px;align-items:baseline}h2{font-size:17px;line-height:1.5;font-weight:850;margin:0}#percent{color:var(--red);font-weight:850;font-variant-numeric:tabular-nums;white-space:nowrap}
progress{display:block;appearance:none;width:100%;height:8px;border:0;background:var(--pale);margin:16px 0;accent-color:var(--red)}progress::-webkit-progress-bar{background:var(--pale)}progress::-webkit-progress-value{background:var(--red)}progress::-moz-progress-bar{background:var(--red)}
#hint{font-size:14px;color:var(--muted);min-height:44px;margin:12px 0 0}button{font:850 15px/1.6 Abyss,sans-serif;color:var(--paper);border:2px solid var(--red);border-radius:0;background:var(--red);width:100%;min-height:48px;margin-top:14px;padding:10px 12px;cursor:pointer}button:hover{background:var(--ink);border-color:var(--ink)}button:focus-visible,a:focus-visible{outline:2px solid var(--ink);outline-offset:3px}[hidden]{display:none!important}
noscript{position:fixed;z-index:3;bottom:24px;left:20px;right:20px;padding:16px;background:var(--paper);color:var(--ink)}
@media(max-height:700px){.status-box{padding-top:12px}}
@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
'''
for key in ['PAPER','INK','ACTION_RED','MUTED','PALE']:style=style.replace(key,color(key))
style=style.replace('BODY_FONT',font('BODY')).replace('BOLD_FONT',font('BOLD'))
text=shell.read_text(encoding='utf-8')
text=re.sub(r'<style>.*?</style>','<style>'+style+'</style>',text,count=1,flags=re.S)
start=text.index('<div id="status"><main class="screen">');end=text.index('<section class="status-box"',start)
brand='<div id="status"><main class="screen">\n<div class="poster"><img class="town-ground" alt="" src="'+bitmap('town.webp')+'"><h1 aria-label="Into the Abyss">'+vector('title-home.svg','brand')+'</h1>'+vector('town-city-left.svg','city-left')+vector('town-city-right.svg','city-right')+vector('town-vermilion.svg','sweep')+'<svg class="portrait" aria-hidden="true" viewBox="25 0 525 659" preserveAspectRatio="xMidYMin slice"><image width="576" height="768" href="'+bitmap('hildegard.webp')+'"/></svg></div>\n'
text=text[:start]+brand+text[end:]
text=re.sub(r'#cloud-challenge\{[^}]+\}', '#cloud-challenge{width:min(100% - 32px,380px);max-height:calc(100% - 32px);overflow:auto;border:3px solid var(--ink);border-radius:0;background:var(--paper);color:var(--ink);padding:24px;font:500 16px/1.6 Abyss,sans-serif}',text)
text=text.replace('#cloud-challenge::backdrop{background:#253c5280}','#cloud-challenge::backdrop{background:#11171580}').replace('#cloud-challenge ::selection{background:#dce8f2;color:#253c52}','#cloud-challenge ::selection{background:var(--red);color:var(--paper)}')
if '--check' in sys.argv:
 assert text==shell.read_text(encoding='utf-8'),'Shell theme assets are stale'
 print('Shell theme colors, fonts and vectors match the town source')
else:
 shell.write_text(text,encoding='utf-8');print('Embedded existing town resources:',len(text.encode()),'bytes')
